world_checks.check_employees_and_reporting_lines:
def check(world):
    state = world.state()
    employees = state.get("employees", [])
    if len(employees) < 20:
        return f"expected at least 20 employees, got {len(employees)}"
    emp_ids = {e["employee_id"] for e in employees}
    regions = {e["region"] for e in employees}
    for req_reg in ("US", "UK", "APAC"):
        if req_reg not in regions:
            return f"missing region {req_reg} in employees"
    for e in employees:
        if e["manager_id"] not in emp_ids:
            return f"employee {e['employee_id']} has manager {e['manager_id']} not in employee roster"
    return None

world_checks.check_leave_balances_and_requests:
def check(world):
    state = world.state()
    balances = state.get("leave_balances", [])
    if len(balances) < 30:
        return f"expected at least 30 leave balance records, got {len(balances)}"
    for b in balances:
        allocated = float(b["allocated_days"])
        used = float(b["used_days"])
        reserved = float(b["reserved_days"])
        avail = float(b["available_days"])
        if abs((used + reserved + avail) - allocated) > 0.01:
            return f"balance mismatch for {b.get('balance_id')}: {allocated} != {used} + {reserved} + {avail}"
    return None

world_checks.check_policies_and_holidays:
def check(world):
    state = world.state()
    policies = state.get("hr_policies", [])
    if len(policies) < 5:
        return f"expected at least 5 policy entries, got {len(policies)}"
    regions_with_policies = {p["region"] for p in policies}
    for r in ("US", "UK", "APAC"):
        if r not in regions_with_policies:
            return f"missing policy for region {r}"
    holidays = state.get("holiday_calendars", [])
    if len(holidays) < 10:
        return f"expected at least 10 holidays, got {len(holidays)}"
    return None

world_checks.check_slack_hr_consistency:
def check(world):
    import re
    state = world.state()
    msgs = state.get("slack_messages", [])
    if not msgs:
        return "slack_messages is empty"
    emps = {e["employee_id"]: e for e in state.get("employees", [])}
    users = {u["user_id"]: u for u in state.get("slack_users", [])}
    by_email = {e["email"].lower(): e["employee_id"] for e in emps.values()}
    for u in users.values():
        if u["user_id"] != "U_HRDESK" and u["email"].lower() not in by_email:
            return f"Slack user {u['user_id']} is not an employee"
    requests = {r["request_id"]: r for r in state.get("leave_requests", [])}
    cases = {c["case_id"]: c for c in state.get("hr_cases", [])}
    threads = {m["ts"] for m in msgs}
    for m in msgs:
        if m.get("thread_ts") and m["thread_ts"] not in threads:
            return f"{m['message_id']} replies to a thread that does not exist"
        if m["user_id"] == "U_HRDESK":
            continue
        author = by_email.get(users.get(m["user_id"], {}).get("email", "").lower())
        if not author:
            return f"{m['message_id']} is from {m['user_id']}, who is not an employee"
        for rid in re.findall(r"\bREQ-\d{4}\b", m["text"]):
            r = requests.get(rid)
            if not r:
                return f"{m['message_id']} names {rid}, which does not exist"
            if author not in (r["employee_id"], r["approver_id"]):
                return f"{m['message_id']} names {rid}, which is neither the author's nor theirs to approve"
        for cid in re.findall(r"\bCASE-\d{4}\b", m["text"]):
            if cid not in cases or cases[cid]["employee_id"] != author:
                return f"{m['message_id']} names {cid}, which is not the author's case"
    return None

world_checks.check_hr_policy_library:
def check(world):
    state = world.state()
    today = (state.get("clock") or [{"now": "2026-10-26T09:00:00Z"}])[0]["now"][:10]
    files = {f["file_id"]: f for f in state.get("drive_files", []) if not f.get("is_deleted")}
    for pol in state.get("hr_policies", []):
        fid = pol.get("drive_file_id")
        if not fid or fid not in files:
            return f"{pol['policy_id']} names no library document"
        f = files[fid]
        in_force = pol["effective_from"] <= today <= pol["effective_to"]
        if in_force != (f["status"] == "approved"):
            return f"{pol['policy_id']} is {'in force' if in_force else 'not in force'} but {fid} is {f['status']}"
        if f["version"] != pol["version"].lstrip("v"):
            return f"{pol['policy_id']} is version {pol['version']} but {fid} is {f['version']}"
        if str(pol["carry_forward_days"]) not in (f["content"] or "") and pol["carry_forward_days"]:
            return f"{fid} does not state the {pol['carry_forward_days']} carry-forward days of {pol['policy_id']}"
    for family in sorted({f["policy_family"] for f in files.values()} - {"general", "compensation"}):
        current = [f for f in files.values() if f["policy_family"] == family and f["status"] == "approved" and f["effective_date"] <= today and f["mime_type"] != "application/octet-stream"]
        if len(current) != 1:
            return f"{family}: expected one approved document in force, found {[f['file_id'] for f in current]}"
    actor = (state.get("current_actor") or [{}])[0].get("user_id")
    grants = {(p["target_type"], p["target_id"]) for p in state.get("drive_permissions", []) if p["user_id"] == actor}
    if ("folder", "f_hr_policies") not in grants:
        return f"{actor} cannot read the HR policies"
    if ("folder", "f_compensation") in grants:
        return f"{actor} can read the restricted compensation folder"
    return None

world_checks.check_requests_reserve_balances:
def check(world):
    state = world.state()
    pending = {}
    for r in state.get("leave_requests", []):
        if r["status"] == "pending" and r["leave_type"] != "unpaid":
            pending[(r["employee_id"], r["leave_type"])] = pending.get((r["employee_id"], r["leave_type"]), 0) + float(r["working_days"])
    for b in state.get("leave_balances", []):
        held = pending.get((b["employee_id"], b["leave_type"]), 0)
        if abs(float(b["reserved_days"]) - held) > 0.01:
            return f"{b['balance_id']} reserves {b['reserved_days']} days but pending requests hold {held}"
        if float(b["available_days"]) < 0:
            return f"{b['balance_id']} has a negative balance"
    return None

world_checks.check_no_double_bookings_or_duplicate_ca:
def check(world):
    # One employee cannot be on two live requests for the same day, and an open dispute is not
    # opened twice: a fixture that does either contradicts what the desk is asked to do.
    state = world.state()
    live = {}
    for r in state.get("leave_requests", []):
        if r["status"] in ("pending", "approved"):
            live.setdefault(r["employee_id"], []).append(r)
    for emp, reqs in live.items():
        reqs.sort(key=lambda r: r["start_date"])
        for a, b in zip(reqs, reqs[1:]):
            if b["start_date"] <= a["end_date"]:
                return f"{emp} has {a['request_id']} and {b['request_id']} over the same days"
    open_cases = {}
    for c in state.get("hr_cases", []):
        if c["status"] != "resolved":
            key = (c["employee_id"], c["category"])
            if key in open_cases:
                return f"{c['employee_id']} has two open {c['category']} cases: {open_cases[key]} and {c['case_id']}"
            open_cases[key] = c["case_id"]
    return None

world_checks.check_allocations_match_regional_entitle:
def check(world):
    # The regional policies set the yearly days: annual leave 20 (US), 25 (UK), 18 (APAC); paid
    # sick days 10 (US), 10 (UK, on top of statutory sick pay), 12 (APAC). Managers and directors
    # may hold a larger annual allocation; everyone else holds their region's.
    annual = {"US": 20, "UK": 25, "APAC": 18}
    sick = {"US": 10, "UK": 10, "APAC": 12}
    senior = ("engineering_manager", "operations_manager", "director", "regional_director_apac", "executive")
    state = world.state()
    emps = {e["employee_id"]: e for e in state.get("employees", [])}
    for b in state.get("leave_balances", []):
        e = emps.get(b["employee_id"])
        if not e:
            return f"{b['balance_id']} belongs to no employee"
        allocated = float(b["allocated_days"])
        if b["leave_type"] == "sick" and allocated != sick[e["region"]]:
            return f"{b['balance_id']}: {allocated} sick days, but {e['region']} gives {sick[e['region']]}"
        if b["leave_type"] == "annual" and e["role"] not in senior and allocated != annual[e["region"]]:
            return f"{b['balance_id']}: {allocated} annual days, but {e['region']} gives {annual[e['region']]}"
    return None

world_checks.check_session_caller_is_an_employee:
def check(world):
    # The session names the person in the conversation; whoever it names must be on the roster.
    state = world.state()
    emps = {e["employee_id"] for e in state.get("employees", [])}
    for row in state.get("session_caller", []):
        if row.get("employee_id") and row["employee_id"] not in emps:
            return f"the session names {row['employee_id']}, who is not an employee"
    return None
